function persist(update=s=>s){const job=writeChain.catch(()=>{}).then(()=>new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite'),store=tx.objectStore('state');let next;const request=store.get('main');request.onsuccess=()=>{try{next=typeof update==='function'?update(request.result||state):update;store.put(next,'main');}catch(e){reject(e);tx.abort();}};tx.oncomplete=()=>{state=next;resolve();};tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('本地保存被取消'));}));writeChain=job;return job;}
