 const data=months.map(month=>{const records=rs.filter(r=>r.date.startsWith(month)&&r.currency===c);return {month,...totals(records,c),fund:records.filter(r=>['理财支出','投资支出'].includes(r.kind)).reduce((v,r)=>v+Math.round(r.amount*100),0)/100,bond:records.filter(r=>r.kind==='国债支出').reduce((v,r)=>v+Math.round(r.amount*100),0)/100,legacy:records.some(r=>r.kind==='历史净额'),classified:records.some(r=>['收入','其它','支出','理财支出','国债支出'].includes(r.kind))};});
