function renderAccounts(){const m=accountMonth||latestBalanceMonth();accountMonth=m;const latest=latestBalanceMonth(),months=[...new Set((currentLedger().snapshots||[]).filter(s=>s.position==='opening'&&s.month<=latest).map(s=>s.month))].sort().reverse();$('balanceMonth').innerHTML=months.map(month=>`<option value="${month}" ${month===m?'selected':''}>${month}</option>`).join('');const bs=accountBalances(currentLedger(),all(),m,accountAsOf);$('accountTitle').textContent=(accountAsOf||m)+' 账户余额';const names={CNY:'人民币',USD:'美元',JPY:'日元',GBP:'英镑',HKD:'港币',EUR:'欧元'};$('currencySummary').hidden=!bs.length;renderConvertedBalance(bs);refreshFx();$('currencyBalances').innerHTML=currencyBalances(bs).map(b=>`<div class="currency-card"><span>${escape(names[b.currency]||b.currency)}总余额 <small>${escape(b.currency)}</small></span><strong>${escape(money(b.amount,b.currency))}</strong>${['USD','JPY'].includes(b.currency)?`<div class="currency-cny" data-currency-cny="${escape(b.currency)}">待汇率</div>`:''}<small>${b.accounts} 个账户合计 · 占比 <b data-currency-share="${escape(b.currency)}">待汇率</b>${b.currency==='CNY'?' · 含投资及国债余额':''}</small></div>`).join('');$('balances').innerHTML=bs.length?bs.map(b=>`<div class="account-line"><span class="account-name">${escape(kindLabel(b.account))}</span><strong class="account-amount">${escape(money(b.amount,b.currency))}</strong><small class="account-source">${escape(b.currency)}</small><span class="account-share" data-account-share="${escape(b.account)}">待汇率</span></div>`).join(''):'<p class="muted">该月份原始记录没有可用的期初余额。流水仍可编辑。</p>';renderBalanceShares(bs);renderBalanceTrend();financeUI.accounts(bs,all(),currentLedger(),fxData?.rates,accountAsOf||balanceUntil(m));}
