async function saveRecord(again=false){if(saving)return;const f=$('recordForm');if(!f.reportValidity())return;saving=true;const old=editingRecord,kind=f.elements.kind.value;const r={...old,id:old?.id||uid(),version:uid(),date:f.elements.date.value,kind,category:f.elements.category.value.trim(),description:f.elements.description.value.trim(),account:f.elements.account.value.trim(),currency:f.elements.currency.value,amount:Math.round(Number(f.elements.amount.value)*100)/100*(kind==='收入'?-1:1),deleted:false,updatedAt:new Date().toISOString()};try{r.tags=normalizeTags(f.elements.tags.value);r.tagSource={method:'manual',at:new Date().toISOString(),reviewed:true};if(!r.tags.length&&!old)r.tags=inferTags(r,currentLedger().meta);if(!isInvestment(r)&&!isValuation(r))delete r.investment;else{const selectedAsset=f.elements.investmentAsset.value,asset=['cn','us'].includes(selectedAsset)?'fund':selectedAsset,action=isValuation(r)?'valuation':f.elements.investmentAction.value;r.investment={...(old?.investment||{}),asset,action,platform:f.elements.investmentPlatform.value.trim()};delete r.investment.market;if(action!=='valuation'){delete r.investment.breakdown;delete r.investment.breakdownPartial;delete r.investment.positionValue;}if(action!=='sell')for(const k of ['remainingValue','positionRemainingValue','costSold','closed'])delete r.investment[k];if(asset==='fund'&&!['cn','us'].includes(selectedAsset)&&!old)throw Error('新投资记录请选择A股或美股；历史合并仅用于保留旧记录。');if(['cn','us'].includes(selectedAsset))r.investment.market=selectedAsset;if(r.investment.market&&(!r.investment.platform||/[|｜+＋]/.test(r.investment.platform)))throw Error('请选择单个平台，不要将多个平台合并填写。');if(r.currency!=='CNY')throw Error('当前投资收益按人民币成本核算，请先填写实际人民币金额。');r.kind=asset==='bond'?(action==='valuation'?'国债余额':'国债支出'):(action==='valuation'?'投资余额':'投资支出');if(action==='buy'||action==='valuation')r.amount=Math.abs(r.amount);else r.amount=-Math.abs(r.amount);if(action==='valuation'&&r.investment.market){const ps=portfolioBefore(all(),old,r.date),target=ps.positions.find(p=>p.market===selectedAsset&&p.platform===r.investment.platform);if(ps.unallocated||!target||target.value===null)throw Error('请先到投资收益 → 更新股票平台拆分估值，完整建立各平台估值。');const breakdown=buildBreakdown(ps.positions.filter(p=>['cn','us'].includes(p.market)&&p.platform!=='历史合并').map(p=>({market:p.market,platform:p.platform,value:p.market===selectedAsset&&p.platform===r.investment.platform?r.amount:p.value})));r.investment.positionValue=r.amount;r.investment.breakdown=breakdown;r.amount=round(breakdown.reduce((n,p)=>n+p.value,0));}else if(action==='valuation'&&old?.investment?.breakdown){r.investment.breakdown=old.investment.breakdown;if(round(r.investment.breakdown.reduce((n,p)=>n+p.value,0))!==r.amount)throw Error('这是一笔平台拆分总估值，请在投资收益的平台拆分界面更新。');}if(action==='sell'){const closed=f.elements.investmentClosed.checked,v=f.elements.remainingValue.value;if(!closed&&!v)throw Error('部分卖出请填写剩余持仓估值；全部卖出请勾选清仓。');r.investment.remainingValue=closed?0:Number(v);r.investment.closed=closed;if(r.investment.market){const ps=portfolioBefore(all(),old,r.date),target=ps.positions.find(p=>p.market===selectedAsset&&p.platform===r.investment.platform);if(!target||target.value===null||ps.unallocated)throw Error('请先补齐各平台拆分估值，再记录股票卖出。');r.investment.positionRemainingValue=r.investment.remainingValue;r.investment.remainingValue=round(ps.groups.find(g=>g.asset==='fund').value-target.value+r.investment.positionRemainingValue);if(closed&&target.cost!==null)r.investment.costSold=target.cost;}if(f.elements.costSold.value)r.investment.costSold=Number(f.elements.costSold.value);}}validateLedger({schema:1,records:[r]});await persist(s=>replacePending(s,r,old));localStorage.setItem('ll-last-account',r.account);$('editor').close();if(!old){$('month').value=r.date.slice(0,7);$('monthEnd').value=$('month').value;$('currency').value=r.currency;}render();toast('已保存到本机，正在同步。');scheduleSync();if(again)openEditor();}catch(e){toast('保存失败：'+e.message);}finally{saving=false;}}
async function deleteRecord(){if(saving||!editingRecord||!confirm('删除这笔账？同步后其他设备也会删除，原始 Excel 不会修改。'))return;const old=editingRecord,record={...old,version:uid(),deleted:true,updatedAt:new Date().toISOString()};await persist(s=>replacePending(s,record,old));$('editor').close();render();toast('已删除，等待同步。');scheduleSync();}
function b64(s){const b=new TextEncoder().encode(s);let v='';for(let i=0;i<b.length;i+=0x8000)v+=String.fromCharCode(...b.subarray(i,i+0x8000));return btoa(v);}
function decode(s){return new TextDecoder().decode(Uint8Array.from(atob(s.replace(/\n/g,'')),c=>c.charCodeAt(0)));}
const githubURL=()=>`https://api.github.com/repos/${REPO}/contents/${PATH.split('/').map(encodeURIComponent).join('/')}?ref=main`;
async function cloudRead(force=false){const known=!force&&!pendingCount()?state.remoteSha:'';if(localMode)return jsonFetch('/api/cloud'+(known?'?knownSha='+encodeURIComponent(known):''));const headers={'Authorization':'Bearer '+token,'Accept':'application/vnd.github+json'};const res=await fetch(githubURL(),{headers,cache:'no-store',signal:AbortSignal.timeout(30000)});if(res.status===404)throw Error('无法读取私有账本，请检查令牌是否授权 LifeLedger 仓库。');if(!res.ok)throw Error(`GitHub 读取失败 (${res.status})`);const meta=await res.json();if(known&&meta.sha===known)return {unchanged:true,sha:known};let ledger;if(meta.content)ledger=JSON.parse(decode(meta.content));else{const r=await fetch(githubURL(),{headers:{...headers,Accept:'application/vnd.github.raw+json'},cache:'no-store',signal:AbortSignal.timeout(30000)});if(!r.ok)throw Error('GitHub 文件读取失败');ledger=await r.json();}validateLedger(ledger);return {ledger,sha:meta.sha};}
async function cloudWrite(ledger,sha){if(localMode)return jsonFetch('/api/cloud',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ledger,sha})});const res=await fetch(githubURL().split('?')[0],{method:'PUT',headers:{'Authorization':'Bearer '+token,'Accept':'application/vnd.github+json','Content-Type':'application/json'},body:JSON.stringify({message:'账本：同步流水',content:b64(JSON.stringify(ledger)),sha,branch:'main'}),signal:AbortSignal.timeout(45000)});if(!res.ok){const e=Error(`GitHub 写入失败 (${res.status})`);e.conflict=[409,422].includes(res.status);throw e;}return res.json();}
async function sync(){if(busy)return;if(!localMode&&!token){syncStatus('已保存在当前设备。请到「同步与备份」连接 GitHub。');return;}if(!navigator.onLine){syncStatus('离线中，修改已保存在当前设备，联网后自动补同步。');return;}const syncStarted=performance.now();busy=true;$('sync').disabled=true;syncStatus('正在同步…');try{
 for(let retry=0;retry<3;retry++){
  let remote=await cloudRead();await persist();if(remote.unchanged){if(pendingCount())remote=await cloudRead(true);else{await persist(s=>({...s,lastSync:new Date().toISOString()}));notice('');syncStatus();logEvent('sync','unchanged',performance.now()-syncStarted);if(pendingCount())scheduleSync();return;}}let writtenSha=remote.sha;const ops=state.pending.slice();const metaOps={...state.pendingMeta};const result=mergePending(remote.ledger,ops);conflicts=result.conflicts;
  if(conflicts.length){await persist(s=>({...s,ledger:remote.ledger}));render();notice('有 '+conflicts.length+' 笔账在两端被修改，请在下方选择保留的版本。');return;}
  const projectMerge=mergeProjectMeta(result.ledger.meta??{},metaOps);if(projectMerge.conflicts.length){await persist(s=>({...s,ledger:remote.ledger}));setView('projects');notice('项目方案在两端被修改，请选择保留版本。');return;}const next={...result.ledger,meta:projectMerge.meta,updatedAt:new Date().toISOString()};
  if(ops.length||Object.keys(metaOps).length){try{const saved=await cloudWrite(next,remote.sha);writtenSha=saved.sha||saved.content?.sha||null;}catch(e){if((e.conflict||e.message.includes('(409)'))&&retry<2)continue;throw e;}}
  await persist(s=>({...acknowledge(s,next,ops,metaOps,new Date().toISOString()),remoteSha:writtenSha}));logEvent('sync','success',performance.now()-syncStarted);notice('');render();if(pendingCount())scheduleSync();return;
 }
}catch(e){logEvent('sync','failed',performance.now()-syncStarted);notice('同步暂未完成：'+e.message+'。当前设备的修改仍保留。');syncStatus('同步失败，待同步修改已保留。');}finally{busy=false;$('sync').disabled=false;}}
function scheduleSync(){clearTimeout(syncTimer);syncTimer=setTimeout(sync,1800);}
function renderConflicts(){ $('conflictsPanel').hidden=!conflicts.length;$('conflicts').innerHTML=conflicts.map(c=>`<div class="conflict"><strong>${escape(c.local.date)} · ${escape(c.local.category)}</strong><pre>本机：${escape([c.local.kind,c.local.description,c.local.account,money(c.local.amount,c.local.currency),c.local.deleted?'已删除':''].join(' · '))}\n云端：${escape(c.remote?[c.remote.kind,c.remote.description,c.remote.account,money(c.remote.amount,c.remote.currency),c.remote.deleted?'已删除':''].join(' · '):'没有这笔记录')}</pre><button class="primary" data-conflict="${escape(c.id)}" data-choice="local">保留本机版本</button> <button class="secondary" data-conflict="${escape(c.id)}" data-choice="remote">保留云端版本</button></div>`).join('');}
async function chooseConflict(id,choice){const c=conflicts.find(x=>x.id===id);if(!c)return;await persist(s=>{const pending=s.pending.filter(p=>p.record.id!==id);if(choice==='local')pending.push({baseVersion:c.remote?.version??null,record:{...c.local,version:uid(),updatedAt:new Date().toISOString()}});return {...s,pending};});conflicts=conflicts.filter(x=>x.id!==id);render();scheduleSync();}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function backup(){if(busy){$('backup').disabled=true;$('backupStatus').textContent='等待当前同步完成，随后自动备份…';while(busy)await new Promise(resolve=>setTimeout(resolve,500));$('backup').disabled=false;}if(localMode){$('backup').disabled=true;$('backupStatus').textContent='正在同步最新账本…';try{await sync();if(pendingCount()){toast('还有未同步修改，请先完成同步。');return;}const began=performance.now();let job=await jsonFetch('/api/backup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:$('nasPath').value})});while(job.state==='running'){ $('backupStatus').textContent=job.stage+' · '+job.percent+'% · '+Math.round((performance.now()-began)/1000)+' 秒';await new Promise(resolve=>setTimeout(resolve,1500));job=await jsonFetch('/api/backup-status');}if(job.state==='failed')throw Error(job.error||'备份失败');const result=job.result;logEvent('backup','success',performance.now()-began);await persist(s=>({...s,ledger:{...s.ledger,meta:{...s.ledger.meta,backupCompleted:result.meta.backupCompleted}}}));render();toast('已备份到极空间。');}catch(e){toast('备份失败：'+e.message);$('backupStatus').textContent=e.message;}finally{$('backup').disabled=false;}}else{if(!token){setView('settings');toast('先连接 GitHub，才能向 Windows 发送备份请求。');return;}await persist(s=>({...s,pendingMeta:{...s.pendingMeta,backupRequest:{id:uid(),requestedAt:new Date().toISOString()}}}));render();await sync();toast(pendingCount()?'请求保存在本机，等待同步。':'已请求 Windows 备份到极空间。');}}
async function restore(file){if(!file)return;if(busy)throw Error('请等待同步完成后再恢复。');const incoming=validateLedger(JSON.parse(await file.text()));if(!confirm(`从文件恢复 ${incoming.records.length} 笔记录？现有不同版本会进入冲突核对。建议先下载当前 JSON。`))return;await persist(s=>{const base=new Map(s.ledger.records.map(r=>[r.id,r]));let pending=s.pending.slice();for(const r of incoming.records){const current=base.get(r.id);if(current&&JSON.stringify(current)===JSON.stringify(r))continue;if(pending.some(o=>o.record.id===r.id))continue;pending.push({baseVersion:current?r.version:null,record:{...r,version:uid(),updatedAt:new Date().toISOString()}});}return {...s,ledger:s.ledger.records.length?s.ledger:{...incoming,records:[]},pending};});render();toast('恢复文件已载入，等待同步。');scheduleSync();}
